import { buildPlayer, buildProjection } from './player.js';

export const appCatalog = {
  files:{title:'文件管理器',size:[790,520],min:[520,340]},
  spreadsheet:{title:'AEROLITH 表格',size:[920,610],min:[620,390]},
  widgets:{title:'小组件中心',size:[760,530],min:[560,380]},
  editor:{title:'程序与文本编辑器',size:[850,580],min:[560,360]},
  browser:{title:'AEROLITH 浏览器',size:[1040,680],min:[700,440]},
  tasks:{title:'执行与资源管理器',size:[890,570],min:[620,390]},
  settings:{title:'系统设置',size:[750,520],min:[540,360]},
  player:{title:'24号 · 场景播放器',size:[940,640],min:[620,420]},
  charts:{title:'实时图表工作台',size:[850,570],min:[600,400]},
  help:{title:'AEROLITH 操作说明',size:[820,600],min:[570,400]},
  system:{title:'嵌套系统',size:[980,690],min:[620,430]},
  projection:{title:'投送视图',size:[930,620],min:[560,380]}
};

const el = (tag, className, html='') => { const node=document.createElement(tag); if(className)node.className=className; node.innerHTML=html; return node; };
const escapeHtml = value => String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

export function buildApp(runtime, win, host) {
  const builders={files:buildFiles,spreadsheet:buildSpreadsheet,widgets:buildWidgets,editor:buildEditor,browser:buildBrowser,tasks:buildTasks,settings:buildSettings,player:buildPlayer,charts:buildCharts,help:buildHelp,system:buildSystem,projection:buildProjection};
  (builders[win.appId]||buildUnknown)(runtime,win,host);
}

function buildSystem(runtime,win,host){
  host.innerHTML='<div class="system-host"><div class="system-host-status"><span class="live-dot"></span><span class="host-label"></span><span class="host-metrics"></span><button class="tool-button host-pause">暂停</button><button class="tool-button host-step">单步 33ms</button><button class="tool-button host-snapshot">保存快照</button><button class="tool-button host-fork">从当前分叉</button></div><div class="nested-mount"></div></div>';
  const sys=runtime.systems.get(win.childId);$('.host-label',host).textContent=`${win.childId} / 第 ${sys.level+1} 层`;const mount=$('.nested-mount',host);runtime.mountDesktop(win.childId,mount);
  $('.host-pause',host).addEventListener('click',()=>{const p=!sys.ownPaused;runtime.setPaused(sys.id,p);$('.host-pause',host).textContent=p?'继续':'暂停';});
  $('.host-step',host).addEventListener('click',()=>runtime.singleStep(sys.id));$('.host-snapshot',host).addEventListener('click',()=>runtime.makeSnapshot(sys.id));$('.host-fork',host).addEventListener('click',()=>runtime.forkSystem(sys.id));
  win.refresh=()=>{$('.host-metrics',host).textContent=`T+${sys.virtualTime.toFixed(2)} · ${sys.actualGrant}/${sys.budget} u · ${sys.state}`;$('.live-dot',host).classList.toggle('paused',runtime.isEffectivelyPaused(sys.id));};win.refresh();
}

function listDirectory(files,path,sortRule='name-asc'){
  const prefix=path==='/'?'/':`${path}/`;const found=new Map();
  for(const [full,item] of Object.entries(files)){if(full===path||!full.startsWith(prefix))continue;const rest=full.slice(prefix.length);const first=rest.split('/')[0];if(!first)continue;const childPath=prefix+first;if(!found.has(childPath))found.set(childPath,rest.includes('/')?{type:'dir'}:item);}
  return [...found.entries()].sort((a,b)=>(a[1].type==='dir'?-1:1)-(b[1].type==='dir'?-1:1)||(sortRule==='name-desc'?-1:1)*a[0].localeCompare(b[0],'zh-CN'));
}

function parentPath(path){if(path==='/')return '/';const parts=path.split('/').filter(Boolean);parts.pop();return '/'+parts.join('/');}
function fileIcon(type){return({dir:'▰',sheet:'Σ',scene:'◈',program:'</>',snapshot:'◉',text:'▤'}[type]||'◇');}

function buildFiles(runtime,win,host){
  const sys=runtime.systems.get(win.systemId);let path=win.filePath&&sys.files[win.filePath]?.type==='dir'?win.filePath:(win.systemId==='outer'?'/Demo':'/Demo');let selected=[];let clipboard=null;
  host.innerHTML=`<div class="app-shell files-app"><div class="app-toolbar"><button class="tool-button files-up">↑</button><button class="tool-button" data-testid="files-new-file">＋ 文件</button><button class="tool-button" data-testid="files-new-folder">＋ 文件夹</button><button class="tool-button" data-testid="files-open">打开</button><button class="tool-button" data-testid="files-copy">复制</button><button class="tool-button files-cut">剪切</button><button class="tool-button" data-testid="files-paste">粘贴</button><button class="tool-button files-delete">删除</button><button class="tool-button files-import">导入</button><button class="tool-button files-export">导出</button><input class="field files-path" data-testid="files-path" value="${path}"></div><div class="split-view"><nav class="side-nav"><button data-testid="files-nav" data-file-path="/Documents">文档</button><button data-testid="files-nav" data-file-path="/Downloads">下载</button><button data-testid="files-nav" data-file-path="/Demo">演示素材</button><button data-testid="files-nav" data-file-path="/Programs">程序</button><button data-testid="files-nav" data-file-path="/System">系统</button><button data-testid="files-nav" data-file-path="/Snapshots">快照</button>${win.systemId==='outer'?'<button data-testid="files-nav" data-file-path="/Recycle Bin">回收站</button>':''}</nav><div class="files-main"><div class="files-head"><span>名称</span><span>类型</span><span>大小</span><span>状态</span></div><div class="files-list" data-testid="files-list"></div></div></div><div class="status-line"><span class="files-status">就绪</span><span>${win.systemId} · 独立文件系统 v${sys.fileVersion}</span></div></div>`;
  const list=$('[data-testid="files-list"]',host);const pathInput=$('[data-testid="files-path"]',host);
  function navigate(next){if(next!=='/'&&!sys.files[next]&&listDirectory(sys.files,next,sys.fileSort).length===0){runtime.notify('路径不存在',next,sys.id);return;}path=next;pathInput.value=path;selected=[];render();}
  function render(){const items=listDirectory(sys.files,path,sys.fileSort);list.replaceChildren();for(const [full,item] of items){const row=el('div','files-row');row.draggable=true;row.dataset.testid='files-item';row.dataset.filePath=full;row.innerHTML=`<span class="file-name"><i>${fileIcon(item.type)}</i>${escapeHtml(full.split('/').pop())}</span><span>${item.type==='dir'?'文件夹':item.type.toUpperCase()}</span><span>${item.type==='dir'?'—':`${Math.max(1,Math.ceil((item.content?.length||0)/1024))} KB`}</span><span>${item.deletedFrom?'可恢复':'本系统'}</span>`;row.addEventListener('click',e=>{if(!e.ctrlKey)selected=[];if(selected.includes(full))selected=selected.filter(x=>x!==full);else selected.push(full);renderSelection();});row.addEventListener('dblclick',()=>open(full,item));row.addEventListener('dragstart',e=>{e.dataTransfer.setData('application/x-nested-file',JSON.stringify({systemId:sys.id,path:full}));e.dataTransfer.effectAllowed='copy';});row.addEventListener('contextmenu',e=>{e.preventDefault();selected=[full];renderSelection();showFileMenu(e.clientX,e.clientY,full,item);});list.append(row);}renderSelection();$('.files-status',host).textContent=`${items.length} 个项目 · ${selected.length} 个已选择`;}
  function renderSelection(){list.querySelectorAll('.files-row').forEach(row=>row.classList.toggle('selected',selected.includes(row.dataset.filePath)));}
  function open(full,item){if(item.type==='dir')return navigate(full);if(item.type==='sheet')return runtime.openWindow(sys.id,'spreadsheet',{filePath:full});if(item.type==='scene')return runtime.openWindow(sys.id==='outer'?(sys.children[0]||sys.id):sys.id,'player',{allowMultiple:true,filePath:full});if(['program','text'].includes(item.type))return runtime.openWindow(sys.id,'editor',{allowMultiple:true,filePath:full});if(item.type==='snapshot'){if(confirm(`恢复 ${full} 中保存的整棵子树吗？范围外系统保持当前状态。`)){const ok=runtime.restoreSnapshot(sys.id,full);if(!ok)runtime.notify('快照恢复失败','文件损坏或版本不兼容',sys.id);}return;}}
  function copyInto(sourceSystem,sourcePath,move=false){const source=runtime.systems.get(sourceSystem);const item=source?.files[sourcePath];if(!item)return;const dest=`${path==='/'?'':path}/${sourcePath.split('/').pop()}`;if(sys.files[dest]&&!confirm(`${dest} 已存在，覆盖吗？`))return;const bytes=(item.content?.length||0);const used=Object.values(sys.files).reduce((n,f)=>n+(f.content?.length||0),0);if(used+bytes>sys.storageLimit*1024){runtime.notify('复制失败','目标系统存储配额不足',sys.id);return;}sys.files[dest]=structuredClone(item);sys.fileVersion++;const fsProcess=sys.processes.find(p=>p.id==='p-fs');if(fsProcess){fsProcess.used+=Math.max(2,Math.ceil(bytes/128));fsProcess.state='ready';}if(move&&sourceSystem===sys.id&&sourcePath!==dest){delete source.files[sourcePath];source.fileVersion++;}runtime.notify(move?'文件已移动':'文件传递完成',`${sourceSystem}:${sourcePath} → ${sys.id}:${dest}`,sys.id);render();}
  list.addEventListener('dragover',e=>{if(e.dataTransfer.types.includes('application/x-nested-file')){e.preventDefault();list.classList.add('drop-target');}});list.addEventListener('dragleave',()=>list.classList.remove('drop-target'));list.addEventListener('drop',e=>{e.preventDefault();list.classList.remove('drop-target');try{const data=JSON.parse(e.dataTransfer.getData('application/x-nested-file'));copyInto(data.systemId,data.path);}catch{runtime.notify('投放失败','无法读取文件传递数据',sys.id);}});
  host.querySelectorAll('[data-testid="files-nav"]').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.filePath)));$('.files-up',host).addEventListener('click',()=>navigate(parentPath(path)));pathInput.addEventListener('keydown',e=>{if(e.key==='Enter')navigate(pathInput.value.trim()||'/');});
  $('[data-testid="files-open"]',host).addEventListener('click',()=>{if(selected[0])open(selected[0],sys.files[selected[0]]||{type:'dir'});});
  $('[data-testid="files-copy"]',host).addEventListener('click',()=>{if(selected[0]){clipboard={systemId:sys.id,path:selected[0],move:false};runtime.clipboard.unshift(`文件：${selected[0]}`);}});$('.files-cut',host).addEventListener('click',()=>{if(selected[0])clipboard={systemId:sys.id,path:selected[0],move:true};});$('[data-testid="files-paste"]',host).addEventListener('click',()=>{if(clipboard){copyInto(clipboard.systemId,clipboard.path,clipboard.move);if(clipboard.move)clipboard=null;}});
  $('[data-testid="files-new-file"]',host).addEventListener('click',()=>{const name=prompt('文件名','新建文档.txt');if(!name)return;const type=name.endsWith('.nos')?'program':name.endsWith('.sheet')?'sheet':name.endsWith('.scene')?'scene':'text',content=type==='sheet'?JSON.stringify({format:'AEROLITH-SHEET/1',cells:{}},null,2):type==='scene'?JSON.stringify({format:'AEROLITH-SCENE/1',name:'最小场景',duration:5,fps:30,vehicle:{type:'object',number:'',palette:['#54d8c1','#f5c34f'],bodyScale:[1.4,1.4,1.4],tailLength:0,mainRotorRadius:0},environment:{terrain:{size:[40,40],amplitude:.1},pads:[{position:[0,0],label:'ORIGIN'}],hangars:0,trees:8,rocks:5},timeline:[{t:0,position:[0,2,0],rotation:[0,0,0]},{t:5,position:[0,2,0],rotation:[0,6.28,0]}]},null,2):'';sys.files[`${path==='/'?'':path}/${name}`]={type,content};sys.fileVersion++;runtime.notify('文件已创建',name,sys.id);render();});
  $('[data-testid="files-new-folder"]',host).addEventListener('click',()=>{const name=prompt('文件夹名','新建文件夹');if(!name)return;sys.files[`${path==='/'?'':path}/${name}`]={type:'dir'};sys.fileVersion++;render();});
  $('.files-delete',host).addEventListener('click',()=>{for(const p of selected){const item=sys.files[p];if(!item)continue;if(sys.id==='outer'&&!p.startsWith('/Recycle Bin')){sys.files[`/Recycle Bin/${p.split('/').pop()}`]={...item,deletedFrom:p};delete sys.files[p];}else delete sys.files[p];}sys.fileVersion++;runtime.notify('文件操作完成',`${selected.length} 个项目已${sys.id==='outer'?'移入回收站':'删除'}`,sys.id);selected=[];render();});
  $('.files-export',host).addEventListener('click',async()=>{const p=selected[0],item=sys.files[p];if(!item||item.type==='dir')return runtime.notify('请选择文件','文件夹不能直接导出',sys.id);const result=await window.hostBridge.exportFile({name:p.split('/').pop(),content:item.content||''});if(!result.canceled)runtime.notify('已保存到本机',result.name,sys.id);});
  $('.files-import',host).addEventListener('click',async()=>{const result=await window.hostBridge.importFile();if(result.canceled)return;const dest=`${path==='/'?'':path}/${result.name}`,type=result.name.endsWith('.nos')?'program':result.name.endsWith('.scene')||result.name.endsWith('.flight')?'scene':result.name.endsWith('.sheet')?'sheet':result.name.endsWith('.snapshot')?'snapshot':'text';sys.files[dest]={type,content:result.content};sys.fileVersion++;render();runtime.notify('已从本机导入',dest,sys.id);});
  function showFileMenu(x,y,full,item){document.querySelectorAll('.context-menu').forEach(m=>m.remove());const m=el('div','context-menu',`<button data-a="open">打开</button>${item.deletedFrom?'<button data-a="restore">恢复到原位置</button>':''}<button data-a="rename">重命名</button><button data-a="copy">复制</button><button data-a="delete">删除</button>`);m.style.left=`${x}px`;m.style.top=`${y}px`;m.addEventListener('click',e=>{const a=e.target.dataset.a;if(a==='open')open(full,item);if(a==='restore'&&item.deletedFrom){const restored={...item};delete restored.deletedFrom;sys.files[item.deletedFrom]=restored;delete sys.files[full];sys.fileVersion++;runtime.notify('文件已恢复',item.deletedFrom,sys.id);render();}if(a==='copy')clipboard={systemId:sys.id,path:full};if(a==='rename'){const n=prompt('新名称',full.split('/').pop());if(n){const dest=parentPath(full)+(parentPath(full)==='/'?'':'/')+n;sys.files[dest]=item;delete sys.files[full];sys.fileVersion++;render();}}if(a==='delete'){$('.files-delete',host).click();}m.remove();});document.body.append(m);}
  win.refresh=()=>{$('.status-line span:last-child',host).textContent=`${sys.id} · 独立文件系统 v${sys.fileVersion}`;};render();
}

function cellAddress(col,row){return String.fromCharCode(65+col)+row;}
function parseRange(range){const [a,b=a]=range.toUpperCase().split(':');const parse=s=>({c:s.charCodeAt(0)-65,r:Number(s.slice(1))});const p=parse(a),q=parse(b);const out=[];for(let r=Math.min(p.r,q.r);r<=Math.max(p.r,q.r);r++)for(let c=Math.min(p.c,q.c);c<=Math.max(p.c,q.c);c++)out.push(cellAddress(c,r));return out;}
function evaluateCells(cells){
  const cache={},visiting=new Set();
  const get=addr=>{addr=addr.toUpperCase();if(!/^[A-J](?:[1-9]|1\d|20)$/.test(addr))return '#REF!';if(addr in cache)return cache[addr];if(visiting.has(addr))return '#CYCLE!';if(!(addr in cells))return 0;visiting.add(addr);const raw=String(cells[addr]??'');let result=raw;if(raw.startsWith('=')){try{let expr=raw.slice(1).replace(/SUM\(([A-Z]+\d+:[A-Z]+\d+)\)/gi,(_m,r)=>{const vals=parseRange(r).map(get);if(vals.some(v=>String(v).startsWith('#')))throw new Error(vals.find(v=>String(v).startsWith('#')));return vals.reduce((n,v)=>n+(Number(v)||0),0);});expr=expr.replace(/\b([A-Z]+\d+)\b/g,(_m,a)=>{const v=get(a);if(String(v).startsWith('#'))throw new Error(v);return Number(v)||0;});if(!/^[\d+\-*/().\s]+$/.test(expr))throw new Error('#VALUE!');result=Function(`"use strict";return (${expr})`)();if(!Number.isFinite(result))result='#DIV/0!';}catch(err){result=String(err.message||'#ERROR!').replace('Error: ','');if(!result.startsWith('#'))result='#ERROR!';}}visiting.delete(addr);cache[addr]=result;return result;};Object.keys(cells).forEach(get);return cache;
}
function workbookFor(runtime,sys,path='/Demo/sample.sheet'){
  if(runtime.workbook&&runtime.workbook.path===path)return runtime.workbook;let data={cells:{}};try{data=JSON.parse(sys.files[path]?.content||'{}');}catch{}runtime.workbook={id:`workbook-${path}`,title:path.split('/').pop(),path,cells:data.cells||{},styles:data.styles||{},values:{},version:1,dirty:false,undo:[],redo:[],open:true};runtime.workbook.values=evaluateCells(runtime.workbook.cells);return runtime.workbook;
}
function publishWorkbook(runtime,book){book.values=evaluateCells(book.cells);book.version++;for(const connection of runtime.chartConnections)connection.queueUpdate?.({version:book.version,values:structuredClone(book.values),cells:structuredClone(book.cells),title:book.title});}

function buildSpreadsheet(runtime,win,host){
  const sys=runtime.systems.get(win.systemId);const book=workbookFor(runtime,sys,win.filePath||'/Demo/sample.sheet');book.open=true;win.workbook=book;let active='A1',anchor='A1';
  host.innerHTML=`<div class="app-shell spreadsheet-app"><div class="sheet-menubar"><button class="tool-button sheet-undo">↶ 撤销</button><button class="tool-button sheet-redo">↷ 重做</button><button class="tool-button sheet-bold">B 粗体</button><button class="tool-button sheet-fill">▧ 标记色</button><button class="tool-button" data-testid="sheet-save">保存</button><span class="sheet-name" data-testid="sheet-filename">${escapeHtml(book.title)}</span><span class="dirty-mark"></span><span class="sheet-version">发布 v${book.version}</span></div><div class="formula-row"><span class="name-box">A1</span><span class="fx">fx</span><input class="field" data-testid="sheet-formula"></div><div class="sheet-scroll"><table data-testid="sheet-grid" class="sheet-grid"></table></div><div class="status-line"><span>工作表 1 · 自动依赖重算</span><span class="calc-state">计算就绪</span></div></div>`;
  const table=$('[data-testid="sheet-grid"]',host);let html='<thead><tr><th></th>';for(let c=0;c<10;c++)html+=`<th>${String.fromCharCode(65+c)}</th>`;html+='</tr></thead><tbody>';for(let r=1;r<=20;r++){html+=`<tr><th>${r}</th>`;for(let c=0;c<10;c++){const addr=cellAddress(c,r);html+=`<td><input data-testid="sheet-cell" data-cell-address="${addr}" aria-label="单元格 ${addr}"></td>`;}html+='</tr>';}table.innerHTML=html+'</tbody>';
  const formula=$('[data-testid="sheet-formula"]',host);const nameBox=$('.name-box',host);
  function selection(){const ac=active.charCodeAt(0),cc=anchor.charCodeAt(0),ar=Number(active.slice(1)),cr=Number(anchor.slice(1)),out=[];for(let r=Math.min(ar,cr);r<=Math.max(ar,cr);r++)for(let c=Math.min(ac,cc);c<=Math.max(ac,cc);c++)out.push(String.fromCharCode(c)+r);return out;}
  function selectionText(){const addrs=selection(),rows=[...new Set(addrs.map(a=>Number(a.slice(1))))],cols=[...new Set(addrs.map(a=>a[0]))];return rows.map(r=>cols.map(c=>book.values[`${c}${r}`]??'').join('\t')).join('\n');}
  function render(){book.values=evaluateCells(book.cells);const chosen=new Set(selection());table.querySelectorAll('[data-cell-address]').forEach(input=>{const addr=input.dataset.cellAddress,style=book.styles[addr]||{};if(document.activeElement!==input)input.value=book.values[addr]??'';input.classList.toggle('formula-cell',String(book.cells[addr]||'').startsWith('='));input.classList.toggle('cell-error',String(book.values[addr]||'').startsWith('#'));input.classList.toggle('range-selected',chosen.has(addr));input.style.fontWeight=style.bold?'700':'';input.style.color=style.color||'';input.style.boxShadow=style.mark?'inset 0 -3px #f5c34f':'';});formula.value=book.cells[active]??'';nameBox.textContent=anchor===active?active:`${anchor}:${active}`;$('.dirty-mark',host).textContent=book.dirty?'● 未保存':'';$('.sheet-version',host).textContent=`发布 v${book.version}`;}
  function commit(addr,value){const before=book.cells[addr]??'';if(before===value)return;book.undo.push({addr,before,after:value});book.redo=[];if(value==='')delete book.cells[addr];else book.cells[addr]=value;book.dirty=true;publishWorkbook(runtime,book);$('.calc-state',host).textContent=`已完成依赖重算 · v${book.version}`;render();}
  table.addEventListener('pointerdown',e=>{const input=e.target.closest('[data-cell-address]');if(!input)return;if(e.shiftKey)active=input.dataset.cellAddress;else anchor=active=input.dataset.cellAddress;render();});table.addEventListener('focusin',e=>{const input=e.target.closest('[data-cell-address]');if(!input)return;active=input.dataset.cellAddress;input.value=book.cells[active]??'';formula.value=input.value;nameBox.textContent=active;input.select();});table.addEventListener('change',e=>{const input=e.target.closest('[data-cell-address]');if(input)commit(input.dataset.cellAddress,input.value);});table.addEventListener('keydown',e=>{const input=e.target.closest('[data-cell-address]');if(!input)return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='c'){const text=selectionText();runtime.clipboard.unshift(text);runtime.clipboard.length=20;navigator.clipboard?.writeText(text);runtime.notify('已复制到剪贴板',`${selection().length} 个单元格`,sys.id,false);}if(e.key==='Enter'){e.preventDefault();commit(input.dataset.cellAddress,input.value);anchor=active=`${input.dataset.cellAddress[0]}${Number(input.dataset.cellAddress.slice(1))+1}`;table.querySelector(`[data-cell-address="${active}"]`)?.focus();}});table.addEventListener('paste',e=>{e.preventDefault();const text=e.clipboardData.getData('text/plain'),rows=text.split(/\r?\n/),startCol=active.charCodeAt(0)-65,startRow=Number(active.slice(1));book.undo.push({addr:active,before:book.cells[active]??'',after:rows[0]?.split('\t')[0]??''});rows.forEach((row,ri)=>row.split('\t').forEach((value,ci)=>{const addr=cellAddress(startCol+ci,startRow+ri);if(value==='')delete book.cells[addr];else book.cells[addr]=value;}));book.dirty=true;publishWorkbook(runtime,book);render();});formula.addEventListener('keydown',e=>{if(e.key==='Enter'){commit(active,formula.value);table.querySelector(`[data-cell-address="${active}"]`)?.focus();}});
  $('.sheet-undo',host).addEventListener('click',()=>{const x=book.undo.pop();if(!x)return;book.redo.push(x);if(x.before==='')delete book.cells[x.addr];else book.cells[x.addr]=x.before;book.dirty=true;publishWorkbook(runtime,book);render();});$('.sheet-redo',host).addEventListener('click',()=>{const x=book.redo.pop();if(!x)return;book.undo.push(x);if(x.after==='')delete book.cells[x.addr];else book.cells[x.addr]=x.after;book.dirty=true;publishWorkbook(runtime,book);render();});
  $('.sheet-bold',host).addEventListener('click',()=>{const turnOn=!book.styles[active]?.bold;for(const addr of selection())book.styles[addr]={...(book.styles[addr]||{}),bold:turnOn};book.dirty=true;render();});$('.sheet-fill',host).addEventListener('click',()=>{const turnOn=!book.styles[active]?.mark;for(const addr of selection())book.styles[addr]={...(book.styles[addr]||{}),mark:turnOn};book.dirty=true;render();});
  $('[data-testid="sheet-save"]',host).addEventListener('click',()=>{sys.files[book.path]={type:'sheet',content:JSON.stringify({format:'AEROLITH-SHEET/1',cells:book.cells,styles:book.styles},null,2)};sys.fileVersion++;book.dirty=false;runtime.persist();render();runtime.notify('工作簿已保存',`${book.path} · 版本 ${book.version}`,sys.id);});win.dispose=()=>{book.open=false;for(const c of runtime.chartConnections)c.sourceClosed?.();};render();
}

function buildWidgets(runtime,win,host){
  const sys=runtime.systems.get(win.systemId);let monthOffset=0;
  host.innerHTML=`<div class="widgets-grid"><section class="widget hero-clock"><div class="widget-label">系统时间</div><strong class="big-time"></strong><span class="big-date"></span><div class="virtual-time"></div></section><section class="widget"><div class="widget-label">倒计时</div><div class="timer-display">00:00</div><input class="field" data-testid="widget-timer-input" type="number" value="5" min="1" max="3600"><div class="button-row"><button class="primary-button" data-testid="widget-timer-start">开始</button><button class="tool-button" data-testid="widget-timer-pause">暂停</button><button class="tool-button" data-testid="widget-timer-reset">复位</button></div></section><section class="widget"><div class="widget-label">便笺</div><textarea data-testid="widget-note-text" placeholder="写点什么…"></textarea><button class="tool-button" data-testid="widget-note-save">保存便笺</button></section><section class="widget calendar-widget"><div class="widget-label">日历 <button class="tool-button cal-prev">‹</button><button class="tool-button cal-next">›</button></div><div class="calendar-title"></div><div class="calendar-grid"></div></section><section class="widget"><div class="widget-label">秒表</div><strong class="stopwatch-time">00:00.0</strong><div class="button-row"><button class="tool-button stopwatch-toggle">开始 / 暂停</button><button class="tool-button stopwatch-reset">清零</button></div></section><section class="widget"><div class="widget-label">剪贴板历史</div><div class="clipboard-list" data-testid="widget-clipboard-list"></div></section><section class="widget"><div class="widget-label">快捷设置 · 与系统设置同步</div><div class="quick-settings"><button class="tool-button quick-wall">切换壁纸</button><button class="tool-button quick-dnd">免打扰：关</button><button class="tool-button quick-accent">切换强调色</button></div></section></div>`;
  const note=$('[data-testid="widget-note-text"]',host);note.value=sys.note;$('[data-testid="widget-note-save"]',host).addEventListener('click',()=>{sys.note=note.value;runtime.notify('便笺已保存',`${note.value.length} 个字符`,sys.id);});$('[data-testid="widget-timer-start"]',host).addEventListener('click',()=>{sys.timer.remaining=Math.max(1,Number($('[data-testid="widget-timer-input"]',host).value)||5);sys.timer.running=true;sys.timer.completed=false;});$('[data-testid="widget-timer-pause"]',host).addEventListener('click',()=>sys.timer.running=false);$('[data-testid="widget-timer-reset"]',host).addEventListener('click',()=>Object.assign(sys.timer,{remaining:0,running:false,completed:false}));$('.stopwatch-toggle',host).addEventListener('click',()=>sys.stopwatch.running=!sys.stopwatch.running);$('.stopwatch-reset',host).addEventListener('click',()=>{sys.stopwatch.elapsed=0;sys.stopwatch.running=false;});$('.cal-prev',host).addEventListener('click',()=>{monthOffset--;renderCalendar();});$('.cal-next',host).addEventListener('click',()=>{monthOffset++;renderCalendar();});
  $('.quick-wall',host).addEventListener('click',()=>{const walls=['aerolith','violet','topo'];sys.settings.wallpaper=walls[(walls.indexOf(sys.settings.wallpaper)+1)%walls.length];runtime.desktops.get(sys.id)?.refreshChrome();});$('.quick-dnd',host).addEventListener('click',e=>{sys.settings.dnd=!sys.settings.dnd;e.target.textContent=`免打扰：${sys.settings.dnd?'开':'关'}`;runtime.desktops.get(sys.id)?.refreshNotifications();});$('.quick-accent',host).addEventListener('click',()=>{const colors=['#f5c34f','#b98cff','#54d8c1','#ff6f7d'];sys.settings.accent=colors[(colors.indexOf(sys.settings.accent)+1)%colors.length];runtime.desktops.get(sys.id)?.refreshChrome();});
  function renderCalendar(){const date=new Date();date.setDate(1);date.setMonth(date.getMonth()+monthOffset);const y=date.getFullYear(),m=date.getMonth();$('.calendar-title',host).textContent=`${y} 年 ${m+1} 月`;const first=new Date(y,m,1).getDay(),days=new Date(y,m+1,0).getDate();let html='日一二三四五六'.split('').map(x=>`<b>${x}</b>`).join('');for(let i=0;i<first;i++)html+='<span></span>';for(let d=1;d<=days;d++)html+=`<span class="${monthOffset===0&&d===new Date().getDate()?'today':''}">${d}</span>`;$('.calendar-grid',host).innerHTML=html;}
  win.refresh=()=>{const now=new Date();$('.big-time',host).textContent=now.toLocaleTimeString('zh-CN');$('.big-date',host).textContent=now.toLocaleDateString('zh-CN',{weekday:'long',year:'numeric',month:'long',day:'numeric'});$('.virtual-time',host).textContent=`虚拟时钟 T+${sys.virtualTime.toFixed(2)}s · ${sys.rate}×`;const rem=Math.ceil(sys.timer.remaining);$('.timer-display',host).textContent=`${String(Math.floor(rem/60)).padStart(2,'0')}:${String(rem%60).padStart(2,'0')}`;const sw=sys.stopwatch.elapsed;$('.stopwatch-time',host).textContent=`${String(Math.floor(sw/60)).padStart(2,'0')}:${(sw%60).toFixed(1).padStart(4,'0')}`;const list=$('[data-testid="widget-clipboard-list"]',host);list.innerHTML=runtime.clipboard.length?runtime.clipboard.slice(0,6).map(x=>`<button>${escapeHtml(String(x).slice(0,80))}</button>`).join(''):'<span class="muted">复制文本或表格单元格后会出现在这里</span>';};renderCalendar();win.refresh();
}

function buildEditor(runtime,win,host){
  const sys=runtime.systems.get(win.systemId);let path=win.filePath||'/Programs/accumulate.nos';if(!sys.files[path])path=Object.keys(sys.files).find(p=>sys.files[p].type==='program')||'/Documents/新程序.nos';
  host.innerHTML=`<div class="app-shell editor-app"><div class="app-toolbar"><select class="field editor-files"></select><input class="field editor-filename" data-testid="editor-filename" value="${escapeHtml(path)}"><button class="primary-button" data-testid="editor-save">保存</button><button class="tool-button editor-run">▶ 编译并运行</button><button class="tool-button editor-new">新建程序</button></div><div class="editor-body"><div class="line-numbers"></div><textarea data-testid="editor-text" spellcheck="false"></textarea></div><div class="editor-console"><div class="console-title">执行控制台 <span>NEST/1 编译器</span></div><pre>等待编译…</pre></div></div>`;
  const select=$('.editor-files',host),filename=$('[data-testid="editor-filename"]',host),text=$('[data-testid="editor-text"]',host),consolePre=$('.editor-console pre',host);const programs=()=>Object.entries(sys.files).filter(([,f])=>['program','text'].includes(f.type));
  function fillSelect(){select.innerHTML=programs().map(([p])=>`<option ${p===path?'selected':''}>${escapeHtml(p)}</option>`).join('');}function load(p){path=p;filename.value=p;text.value=sys.files[p]?.content||'';updateLines();fillSelect();}function updateLines(){$('.line-numbers',host).innerHTML=text.value.split('\n').map((_x,i)=>`<span>${i+1}</span>`).join('');}select.addEventListener('change',()=>load(select.value));text.addEventListener('input',updateLines);text.addEventListener('scroll',()=>$('.line-numbers',host).scrollTop=text.scrollTop);
  $('[data-testid="editor-save"]',host).addEventListener('click',()=>{path=filename.value.trim()||path;sys.files[path]={type:path.endsWith('.nos')?'program':'text',content:text.value};sys.fileVersion++;runtime.notify('文件已保存',path,sys.id);fillSelect();});$('.editor-run',host).addEventListener('click',()=>{try{const p=runtime.compileAndRun(sys.id,path,text.value);consolePre.textContent=`编译成功\nPID ${p.id}\n${p.instructions.length} 条指令已装载\n该进程将与内核及应用竞争预算。`;win.refresh=()=>{consolePre.textContent=`PID ${p.id} · ${p.state}\n已执行 ${p.used} u · 剩余 ${p.remaining} u\nPC ${p.pc}\n\n${p.output.join('\n')}`;};}catch(err){consolePre.textContent=`编译失败\n${err.message}`;runtime.notify('编译失败',err.message,sys.id);}});$('.editor-new',host).addEventListener('click',()=>{path='/Programs/untitled.nos';filename.value=path;text.value='PROGRAM 新程序\nSET counter 0\nLOOP 10\nADD counter 1\nEND\nPRINT counter\nHALT';updateLines();});load(path);
}

function storageUsed(sys){return Object.values(sys.files).reduce((n,f)=>n+(f.content?.length||0),0)/1024;}
function buildTasks(runtime,win,host){
  const sys=runtime.systems.get(win.systemId);host.innerHTML=`<div class="app-shell tasks-app"><div class="resource-strip"><label>逻辑预算 <input data-testid="tasks-budget" type="range" min="80" max="1600" value="${sys.budget}"><b class="budget-value"></b></label><label>内存配额 <input data-testid="tasks-memory" type="range" min="128" max="4096" value="${sys.memoryLimit}"><b class="memory-value"></b></label><label>存储配额 <input data-testid="tasks-storage" type="range" min="256" max="8192" value="${sys.storageLimit}"><b class="storage-value"></b></label></div><div class="tasks-summary"><div><small>本步实际拨付</small><strong class="actual-grant">0 u</strong></div><div><small>内核与服务消耗</small><strong class="actual-used">0 u</strong></div><div><small>虚拟时间</small><strong class="virtual-clock">0.00 s</strong></div><div><small>调度策略</small><strong>${escapeHtml(sys.scheduler)}</strong></div></div><div class="process-head"><span>进程 / 职责</span><span>状态</span><span>累计工作</span><span>剩余</span><span>内存</span><span>额度</span><span>控制</span></div><div class="process-list"></div><div class="status-line"><span>逻辑单位 u：每条指令或一次明确定义计算步骤</span><span>网页 Chromium 工作不计入此处</span></div></div>`;
  const budget=$('[data-testid="tasks-budget"]',host),memory=$('[data-testid="tasks-memory"]',host),storage=$('[data-testid="tasks-storage"]',host);budget.addEventListener('input',()=>sys.budget=Number(budget.value));memory.addEventListener('input',()=>sys.memoryLimit=Number(memory.value));storage.addEventListener('input',()=>sys.storageLimit=Number(storage.value));
  function render(){const list=$('.process-list',host);list.innerHTML=sys.processes.map(p=>`<div class="process-row" data-pid="${p.id}"><span><b>${escapeHtml(p.name)}</b><small>${escapeHtml(p.role)} ${p.childId?'· 内核/内部工作分列':''}${p.external?' · 不计入指令预算':''}${p.error?`<em class="proc-error"> · ${escapeHtml(p.error)}</em>`:''}</small></span><span class="proc-state ${p.state}">${p.state}</span><span>${p.external?'—':Math.round(p.used)+' u'}</span><span>${p.external?'—':Math.round(p.remaining||0)+' u'}</span><span>${Number(p.memory||0).toFixed(1)} MB</span><span><input data-testid="tasks-grant" data-target-system-id="${p.childId||''}" type="number" value="${p.quota||0}" min="0" max="1200" ${p.external?'disabled':''}></span><span><button data-a="toggle" ${p.external?'disabled':''}>${p.state==='suspended'?'继续':'挂起'}</button><button data-a="end">结束</button></span></div>`).join('');list.querySelectorAll('.process-row').forEach(row=>{const p=sys.processes.find(x=>x.id===row.dataset.pid);row.querySelector('[data-a="toggle"]').addEventListener('click',()=>{p.state=p.state==='suspended'?'ready':'suspended';render();});row.querySelector('[data-a="end"]').addEventListener('click',()=>{if(p.childId){const w=[...runtime.windows.values()].find(x=>x.childId===p.childId);if(w)runtime.closeWindow(w,true);runtime.stopSubtree(p.childId);}else if(p.external&&p.tabId){runtime.windows.get(p.windowId)?.closeBrowserTab?.(p.tabId);}else if(p.windowId){runtime.closeWindow(runtime.windows.get(p.windowId));}else p.state='ended';render();});row.querySelector('[data-testid="tasks-grant"]').addEventListener('change',e=>{p.quota=Number(e.target.value);if(p.childId)runtime.systems.get(p.childId).grant=p.quota;});});$('.budget-value',host).textContent=`${sys.budget} u/步`;$('.memory-value',host).textContent=`${sys.processes.reduce((n,p)=>n+(p.memory||0),0).toFixed(0)} / ${sys.memoryLimit} MB`;$('.storage-value',host).textContent=`${storageUsed(sys).toFixed(1)} / ${sys.storageLimit} KB`;$('.actual-grant',host).textContent=`${sys.actualGrant} u`;$('.actual-used',host).textContent=`${sys.workUsed} u`;$('.virtual-clock',host).textContent=`${sys.virtualTime.toFixed(2)} s`;}
  win.refresh=render;render();
}

function buildSettings(runtime,win,host){
  const sys=runtime.systems.get(win.systemId);host.innerHTML=`<div class="settings-layout"><nav class="settings-nav"><div class="settings-brand"><b>AEROLITH</b><span>系统设置</span></div><button class="active">个性化</button><button>系统与资源</button><button>通知</button><button>关于</button></nav><div class="settings-page"><h2>个性化</h2><p>设置只影响 ${escapeHtml(sys.name)}，并与快捷设置共享。</p><section><h3>系统名称</h3><input class="field system-name" value="${escapeHtml(sys.name)}"></section><section><h3>壁纸</h3><div class="wall-options" data-testid="settings-wallpaper"><button data-value="aerolith" class="wall-aerolith-preview">暮色山脊</button><button data-value="violet" class="wall-violet-preview">紫晶深谷</button><button data-value="topo" class="wall-topo-preview">地形等高线</button></div></section><section><h3>强调色</h3><div class="accent-options" data-testid="settings-accent">${['#f5c34f','#b98cff','#54d8c1','#ff6f7d','#62a8ff'].map(c=>`<button data-value="${c}" style="--swatch:${c}" aria-label="强调色 ${c}"></button>`).join('')}</div></section><section><h3>界面缩放 <b class="scale-value">${Math.round(sys.settings.scale*100)}%</b></h3><input data-testid="settings-scale" type="range" min="0.85" max="1.2" step="0.05" value="${sys.settings.scale}"></section><section class="about-card"><b>NEST kernel ${sys.scheduler}</b><span>Electron ${window.hostBridge?.versions.electron} · Chromium ${window.hostBridge?.versions.chrome}</span></section></div></div>`;
  $('.system-name',host).addEventListener('change',e=>{sys.name=e.target.value;runtime.desktops.get(sys.id)?.renderStart();runtime.desktops.get(sys.parentId)?.refreshChrome();});host.querySelectorAll('[data-testid="settings-wallpaper"] button').forEach(b=>b.addEventListener('click',()=>{sys.settings.wallpaper=b.dataset.value;runtime.desktops.get(sys.id)?.refreshChrome();}));host.querySelectorAll('[data-testid="settings-accent"] button').forEach(b=>b.addEventListener('click',()=>{sys.settings.accent=b.dataset.value;runtime.desktops.get(sys.id)?.refreshChrome();}));const scale=$('[data-testid="settings-scale"]',host);scale.addEventListener('input',()=>{sys.settings.scale=Number(scale.value);$('.scale-value',host).textContent=`${Math.round(sys.settings.scale*100)}%`;runtime.desktops.get(sys.id)?.refreshChrome();});
}

function normalizeUrl(value){let url=value.trim();if(!url)return 'https://www.bilibili.com';if(!/^[a-z]+:\/\//i.test(url)){if(url.includes('.')&&!url.includes(' '))url='https://'+url;else url='https://www.bing.com/search?q='+encodeURIComponent(url);}return url;}
function buildBrowser(runtime,win,host){
  const sys=runtime.systems.get(win.systemId);let counter=1;win.browserTabs=[];let active=null;host.innerHTML=`<div class="browser-shell"><div class="browser-tabs"><div class="browser-tab-list"></div><button data-testid="browser-new-tab" class="new-tab">＋</button><span class="browser-engine">CHROMIUM</span></div><div class="browser-nav"><button data-testid="browser-back" aria-label="后退">←</button><button data-testid="browser-forward" aria-label="前进">→</button><button data-testid="browser-reload" aria-label="刷新">↻</button><div class="address-wrap"><span>⌁</span><input data-testid="browser-address" value="https://www.bilibili.com" aria-label="地址栏"><i class="load-pulse"></i></div><button data-testid="browser-go">前往</button></div><div class="webview-stack"></div><div class="browser-status">真实 Chromium 隔离视图 · 外部页面不计入逻辑预算</div></div>`;
  const stack=$('.webview-stack',host),tabsEl=$('.browser-tab-list',host),address=$('[data-testid="browser-address"]',host);
  function addTab(url='https://www.bilibili.com'){const tab={id:`tab-${counter++}`,url,title:'新标签',loadState:'loading',view:document.createElement('webview')};const proc={id:`web-${win.id}-${tab.id}`,name:`Chromium ${tab.id}`,role:'网页视图（宿主边界）',state:'loading',used:0,remaining:0,memory:72,quota:0,pc:0,windowId:win.id,tabId:tab.id,external:true,output:['不计入 NEST 指令']};sys.processes.push(proc);tab.process=proc;tab.view.setAttribute('partition','persist:aerolith-browser');tab.view.setAttribute('allowpopups','');tab.view.src=url;tab.view.className='browser-webview';tab.view.addEventListener('did-start-loading',()=>{tab.loadState='loading';proc.state='loading';renderTabs();});tab.view.addEventListener('did-stop-loading',()=>{tab.loadState='loaded';proc.state='external';tab.url=tab.view.getURL();tab.title=tab.view.getTitle()||tab.url;proc.name=`Chromium · ${tab.title.slice(0,24)}`;if(active===tab){address.value=tab.url;$('.browser-status',host).textContent=`已完成 · ${tab.title}`;}renderTabs();});tab.view.addEventListener('did-fail-load',e=>{if(e.errorCode===-3)return;tab.loadState='error';proc.state='error';proc.output.unshift(e.errorDescription);$('.browser-status',host).textContent=`加载失败：${e.errorDescription} · 可刷新重试`;renderTabs();});tab.view.addEventListener('page-title-updated',e=>{tab.title=e.title;renderTabs();});stack.append(tab.view);win.browserTabs.push(tab);switchTab(tab);}
  function switchTab(tab){active=tab;win.browserTabs.forEach(t=>t.view.classList.toggle('active',t===tab));address.value=tab.url;renderTabs();}
  function renderTabs(){tabsEl.innerHTML='';for(const tab of win.browserTabs){const b=el('button',`browser-tab ${tab===active?'active':''}`);b.dataset.testid='browser-tab';b.dataset.tabId=tab.id;b.innerHTML=`<span class="tab-state ${tab.loadState}"></span><span>${escapeHtml(tab.title).slice(0,28)}</span><i data-testid="browser-close-tab">×</i>`;b.addEventListener('click',e=>{if(e.target.tagName==='I')closeTab(tab);else switchTab(tab);});tabsEl.append(b);}}
  function closeTab(tab){tab.view.remove();sys.processes=sys.processes.filter(p=>p!==tab.process);win.browserTabs=win.browserTabs.filter(t=>t!==tab);if(!win.browserTabs.length)addTab('https://www.bilibili.com');else if(active===tab)switchTab(win.browserTabs.at(-1));renderTabs();}
  function go(){const url=normalizeUrl(address.value);active.url=url;active.loadState='loading';active.view.loadURL(url);renderTabs();}
  $('[data-testid="browser-new-tab"]',host).addEventListener('click',()=>addTab('https://www.bilibili.com'));$('[data-testid="browser-go"]',host).addEventListener('click',go);address.addEventListener('keydown',e=>{if(e.key==='Enter')go();});$('[data-testid="browser-back"]',host).addEventListener('click',()=>active.view.canGoBack()&&active.view.goBack());$('[data-testid="browser-forward"]',host).addEventListener('click',()=>active.view.canGoForward()&&active.view.goForward());$('[data-testid="browser-reload"]',host).addEventListener('click',()=>active.loadState==='loading'?active.view.stop():active.view.reload());win.closeBrowserTab=tabId=>{const tab=win.browserTabs.find(t=>t.id===tabId);if(tab)closeTab(tab);};win.dispose=()=>win.browserTabs.forEach(t=>t.view.remove());win.onVisibility=visible=>win.browserTabs.forEach(t=>t.view.style.visibility=visible?'visible':'hidden');addTab();
}

function extractChartData(book,range,labelColumn,series){const addresses=parseRange(range);const rows=[...new Set(addresses.map(a=>Number(a.match(/\d+/)[0])))];const cols=[...new Set(addresses.map(a=>a.match(/[A-Z]+/)[0]))];const label=labelColumn||cols[0];const seriesCols=series.filter(c=>cols.includes(c));return{labels:rows.slice(1).map(r=>String(book.values[`${label}${r}`]??'')),series:seriesCols.map(c=>({name:String(book.values[`${c}${rows[0]}`]??c),values:rows.slice(1).map(r=>Number(book.values[`${c}${r}`])||0)}))};}
function drawChart(canvas,state){const dpr=devicePixelRatio||1,rect=canvas.getBoundingClientRect();const w=Math.max(320,rect.width),h=Math.max(220,rect.height);if(canvas.width!==w*dpr||canvas.height!==h*dpr){canvas.width=w*dpr;canvas.height=h*dpr;}const ctx=canvas.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);ctx.fillStyle='#0a1323';ctx.fillRect(0,0,w,h);const data=state.data||{labels:[],series:[]},pad={l:55,r:24,t:48,b:48};ctx.fillStyle='#eaf1fa';ctx.font='600 14px Microsoft YaHei';ctx.fillText(state.sourceTitle||'等待数据',pad.l,25);const all=data.series.flatMap(s=>s.values),max=Math.max(1,...all)*1.15;ctx.strokeStyle='rgba(255,255,255,.1)';ctx.fillStyle='#7f8da3';ctx.font='10px Microsoft YaHei';for(let i=0;i<=4;i++){const y=pad.t+(h-pad.t-pad.b)*i/4;ctx.beginPath();ctx.moveTo(pad.l,y);ctx.lineTo(w-pad.r,y);ctx.stroke();ctx.fillText(Math.round(max*(1-i/4)),10,y+3);}const plotW=w-pad.l-pad.r,plotH=h-pad.t-pad.b,colors=['#f5c34f','#b98cff','#54d8c1','#ff7383'];data.labels.forEach((label,i)=>{const x=pad.l+plotW*(i+.5)/Math.max(1,data.labels.length);ctx.fillStyle='#aebace';ctx.fillText(label,x-18,h-20);});data.series.forEach((s,si)=>{ctx.strokeStyle=ctx.fillStyle=colors[si%colors.length];ctx.lineWidth=3;if(state.type==='line'){ctx.beginPath();s.values.forEach((v,i)=>{const x=pad.l+plotW*(i+.5)/data.labels.length,y=pad.t+plotH*(1-v/max);i?ctx.lineTo(x,y):ctx.moveTo(x,y);});ctx.stroke();s.values.forEach((v,i)=>{const x=pad.l+plotW*(i+.5)/data.labels.length,y=pad.t+plotH*(1-v/max);ctx.beginPath();ctx.arc(x,y,5,0,Math.PI*2);ctx.fill();ctx.fillStyle='#e9eff8';ctx.fillText(v,x-7,y-10);ctx.fillStyle=colors[si%colors.length];});}else{s.values.forEach((v,i)=>{const group=plotW/data.labels.length,bw=Math.min(42,group*.65/data.series.length),x=pad.l+group*i+group*.17+si*bw,y=pad.t+plotH*(1-v/max);ctx.fillRect(x,y,bw-3,pad.t+plotH-y);ctx.fillStyle='#eef3fb';ctx.fillText(v,x+2,y-7);ctx.fillStyle=colors[si%colors.length];});}ctx.fillStyle=colors[si%colors.length];ctx.fillRect(pad.l+si*110,h-9,12,3);ctx.fillStyle='#bbc6d6';ctx.fillText(s.name,pad.l+17+si*110,h-5);});}
function buildCharts(runtime,win,host){
  const sys=runtime.systems.get(win.systemId);win.chartState={sourceTitle:'sample.sheet',range:'A1:D4',labelColumn:'A',series:['D'],type:'bar',connectionState:'disconnected',data:null,version:0,queue:[]};const state=win.chartState;
  host.innerHTML=`<div class="app-shell chart-app"><div class="chart-controls"><label>数据源<select data-testid="chart-source" class="field"><option value="workbook-sample">sample.sheet（已打开）</option></select></label><label>区域<input data-testid="chart-range" class="field" value="A1:D4"></label><label>标签列<input data-testid="chart-label-column" class="field" value="A"></label><label>数值列<input data-testid="chart-series" class="field" value="D"></label><button class="primary-button" data-testid="chart-connect">连接</button><button class="tool-button" data-testid="chart-disconnect">断开</button><select data-testid="chart-type" class="field"><option value="bar">分组柱状图</option><option value="line">折线图</option></select><button class="tool-button" data-testid="window-project">投送 ↗</button><select class="field" data-testid="project-target"></select></div><div class="chart-stage"><canvas></canvas><div class="chart-overlay"><span class="connection-badge">未连接</span><span class="chart-version">v0</span></div></div><div class="status-line"><span>接收进程 → 消息队列 → 图表计算进程 → 显示提交</span><span class="chart-work">0 u</span></div></div>`;
  const canvas=$('canvas',host),target=$('[data-testid="project-target"]',host);target.innerHTML=runtime.ancestors(sys.id).map(a=>`<option value="${a.id}" data-target-system-id="${a.id}">${a.id} · ${escapeHtml(a.name)}</option>`).join('');
  const connection={systemId:sys.id,windowId:win.id,state,queueUpdate(payload){if(state.connectionState==='connected'&&payload.version>state.version){state.queue.push(payload);state.pendingWork=20+Object.keys(payload.values).length*2;}},tick(budget){if(state.connectionState!=='connected'||!state.queue.length||runtime.isEffectivelyPaused(sys.id))return 0;const use=Math.min(budget||0,state.pendingWork||1,12);state.pendingWork-=use;if(state.pendingWork<=0){const payload=state.queue.shift();state.version=payload.version;state.data=extractChartData({values:payload.values},state.range,state.labelColumn,state.series);if(sys.chartScale&&sys.chartScale!==1)state.data.series.forEach(series=>series.values=series.values.map(value=>value*sys.chartScale));state.pendingWork=state.queue.length?20:0;drawChart(canvas,state);runtime.submitDisplay(win);}return use;},sourceClosed(){if(state.connectionState==='connected'){state.connectionState='source-closed';renderStatus();}}};runtime.chartConnections.add(connection);win.chartConnection=connection;
  function connect(){const book=runtime.workbook||workbookFor(runtime,runtime.systems.get('outer'));state.range=$('[data-testid="chart-range"]',host).value.toUpperCase();state.labelColumn=$('[data-testid="chart-label-column"]',host).value.toUpperCase();state.series=$('[data-testid="chart-series"]',host).value.toUpperCase().split(/[ ,]+/).filter(Boolean);state.sourceTitle=book.title;state.connectionState='connected';connection.queueUpdate({version:book.version,values:structuredClone(book.values),cells:structuredClone(book.cells),title:book.title});renderStatus();}
  function renderStatus(){const badge=$('.connection-badge',host);badge.textContent=({connected:'● 实时连接',disconnected:'○ 未连接','source-closed':'△ 数据源已关闭'}[state.connectionState]||state.connectionState);badge.className=`connection-badge ${state.connectionState}`;$('.chart-version',host).textContent=`v${state.version}`;$('.chart-work',host).textContent=`积压 ${state.queue.length} 版 · 剩余 ${state.pendingWork||0} u`;}
  win.handleAppMessage=message=>{if(message.type==='chart-type'){state.type=message.payload;$('[data-testid="chart-type"]',host).value=state.type;drawChart(canvas,state);for(const p of runtime.windows.values())if(p.appId==='projection'&&p.sourceWindowId===win.id)p.refresh?.();}};$('[data-testid="chart-connect"]',host).addEventListener('click',connect);$('[data-testid="chart-disconnect"]',host).addEventListener('click',()=>{state.connectionState='disconnected';state.queue=[];renderStatus();});$('[data-testid="chart-type"]',host).addEventListener('change',e=>runtime.sendAppMessage(win,'chart-type',e.target.value));$('[data-testid="window-project"]',host).addEventListener('click',()=>projectWindow(runtime,win,target.value));canvas.addEventListener('mousemove',e=>{$('.status-line span:first-child',host).textContent=`指针坐标 ${Math.round(e.offsetX)}, ${Math.round(e.offsetY)} · 数据版本 ${state.version}`;});win.refresh=()=>{renderStatus();drawChart(canvas,state);};win.onResize=()=>drawChart(canvas,state);win.dispose=()=>runtime.chartConnections.delete(connection);drawChart(canvas,state);renderStatus();
}

export function projectWindow(runtime,source,targetId){if(!targetId)return;if(runtime.projections.has(source.id)){const existing=runtime.windows.get(runtime.projections.get(source.id));existing?.restore();existing?.focus();return existing;}const p=runtime.openWindow(targetId,'projection',{title:`投送 · ${source.title}`,sourceWindowId:source.id,allowMultiple:true,x:180,y:85,width:920,height:620});runtime.projections.set(source.id,p.id);runtime.submitDisplay(source);runtime.notify('窗口已投送',`${source.systemId}/${source.appId} → ${targetId}`,targetId);return p;}

function buildHelp(_runtime,_win,host){host.innerHTML=`<div class="help-layout"><aside><b>AEROLITH</b><a href="#quick">快速开始</a><a href="#program">程序格式</a><a href="#kernel">内核与预算</a><a href="#flight">飞行与场景</a><a href="#data">数据与投送</a><a href="#snapshot">快照</a></aside><article><h1 id="quick">嵌套操作系统操作说明</h1><p>桌面采用熟悉的窗口、开始菜单和任务栏。双击图标启动应用；拖动标题栏到左右边缘可贴靠；子系统完整运行在父系统的承载窗口中。</p><div class="help-callout">每一层都有独立的文件、进程、虚拟时钟、桌面与资源配额。暂停中间层会冻结整棵子树，但外层与兄弟分支照常运行。</div><h2 id="program">NEST/1 程序格式与系统接口</h2><p>程序位于 <code>/Programs/*.nos</code>。第一行为 <code>PROGRAM 名称</code>，支持 <code>SET</code>、<code>ADD</code>、<code>LOOP n</code>、<code>FOREVER</code>、<code>END</code>、<code>WAIT 秒</code>、<code>SEND 进程 值</code>、<code>RECV 变量</code>、<code>WRITE 路径 值</code>、<code>DISPLAY 值</code>、<code>CALL 系统调用 结果变量</code>、<code>PRINT</code> 与 <code>HALT</code>。变量、PC、循环栈、等待和消息队列都进入快照。</p><pre>PROGRAM 示例\nSET total 0\nLOOP 100\nADD total 1\nEND\nPRINT total\nHALT</pre><h2 id="kernel">内核、调度与计量</h2><p>直属子系统内核位于父系统的 <code>/Systems/inner-N/kernel.nos</code>。在父系统编辑器修改 <code>SCHEDULER</code>、<code>MESSAGE</code>、<code>FILES</code>，或增加 <code>SYSCALL answer RETURN 42</code> 后，用顶部 K 打开、↻ 重启。窗口和文件规则分别来自子系统的 <code>/System/window-manager.nos</code> 与 <code>/System/file-manager.nos</code>。语法错误只会阻止对应子树。</p><p>一个逻辑单位 u 是一条 NEST 指令或一次明确定义的应用计算。内核、文件、图表、飞行、显示提交和承载进程共享每步预算；额度只是上限。网页执行与 GPU 实际绘制不计入 u。</p><h2 id="flight">场景、播放器与飞控</h2><p><code>/Demo/helicopter-24.scene</code> 是 AEROLITH-SCENE/1 数据资源：vehicle、environment、timeline、effects、材质与镜头来自文件。播放器 30 FPS，逐帧为 1/30 秒。飞控在 <code>/System/flight-control.nos</code>，接口为带时间戳的 <code>SENSE attitude altitude heading</code> 与保持型 <code>CONTROL collective/cyclic</code>。降低祖先拨付、提高时间倍率或运行持续计算会使控制周期错过并影响飞行。</p><pre>{ "format":"AEROLITH-SCENE/1", "duration":5,\n  "vehicle":{"type":"object","palette":["#54d8c1","#f5c34f"],"bodyScale":[1,1,1]},\n  "environment":{"terrain":{"size":[40,40]},"pads":[{"position":[0,0],"label":"ORIGIN"}]},\n  "timeline":[{"t":0,"position":[0,2,0],"rotation":[0,0,0]}, {"t":5,"position":[0,2,0],"rotation":[0,6.28,0]}] }</pre><p>排演保存为 AEROLITH-FLIGHT/1，记录场景路径、输入、实际控制和状态帧；重新打开后回放与当前预算无关。工作簿为 AEROLITH-SHEET/1，<code>cells</code> 保存原值和公式。</p><h2 id="data">实时数据与投送</h2><p>图表按工作簿身份和矩形区域连接。每次表格提交与公式重算后，完整值副本经消息进入目标系统。投送只在祖先桌面创建外框与显示副本，计算仍属于源系统；投送输入回到源应用队列。</p><h2 id="snapshot">快照、分叉与文件</h2><p>顶部 ◉ 保存子树同一逻辑时点的内核、进程、消息、文件、窗口、播放器与图表状态；在父系统文件管理器双击 <code>.snapshot</code> 恢复，⑂ 以新身份分叉。跨层拖放得到独立文件副本，实时连接不是文件复制。</p></article></div>`;}
function buildUnknown(_runtime,_win,host){host.innerHTML='<div class="empty-state"><strong>应用不可用</strong><span>未找到这个程序的入口。</span></div>';}

function $(selector,root=document){return root.querySelector(selector);}
